\set T '''00000000-0000-0000-0000-000000000001'''
\set O '''00000000-0000-0000-0000-0000000000a1'''
\set O2 '''00000000-0000-0000-0000-0000000000a2'''
-- bills: B1 PAID (2 item lines, tax 5% as 2.5+2.5), B2 GENERATED, B3 PAID (other order), B4 PAID (for void/coupon tests)
-- TEST-ONLY: let the test statements omit ids on V001-V004 tables (production code always supplies uuids)
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='id' AND data_type='uuid' AND column_default IS NULL LOOP
  EXECUTE format('ALTER TABLE %I ALTER COLUMN id SET DEFAULT gen_random_uuid()', r.table_name);
 END LOOP; END $$;
